import './../styles/article.css'
import {articleList} from '../datas/articleList.js'


function Article() {
    return (
        <div className="article-container">
            {articleList.map((article) => (
                <div className="card">
                    {article.promo &&
                        <div className="promo"> 
                            <p>{article.promo ? "Solde" : ""}</p>
                        </div>
                    }
                    <img src={article.image} alt={article.nom} className="card-image"/>
                    <p>{article.prix}€</p>
                    <p>{article.nom}</p>
                </div>
            ))}
        </div>
    
    )
}
export default Article;
